using System;
using System.Drawing;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace DoomSNESed {
    public sealed class MusicMappingDialog:Form {
        EventHandler sampleSelectionChanged;void SampleSelectionChanged(object sender,EventArgs e){if(sampleSelectionChanged!=null)sampleSelectionChanged(sender,e);}public MusicSettings Settings;System.Media.SoundPlayer player;System.IO.MemoryStream stream;
        static string PriorityName(int value){return value<=-6?"Lowest":value<0?"Background":value==0?"Normal":value<6?"Important":"Keep";}public MusicMappingDialog(byte[] rom,ImportedMusic source,MusicSettings settings){
            Text="MIDI channel / instrument assignments";Size=new Size(960,650);MinimumSize=new Size(800,500);StartPosition=FormStartPosition.CenterParent;BackColor=Theme.Background;ForeColor=Theme.Text;Font=new Font("Segoe UI",10);
            var available=MusicBank.All(rom);var library=available.SelectMany(b=>b.Instruments).GroupBy(i=>i.Id).Select(g=>g.First()).OrderBy(i=>i.Id).ToList();var banks=available.Where(b=>source.Notes.All(n=>b.Instruments.Any(i=>NativeVoicing.Percussion(i.Id)==(n.Channel==9)))).ToList();var bank=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=510,BackColor=Theme.Raised,ForeColor=Theme.Text};foreach(var item in banks)bank.Items.Add(item);
            var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=130,Padding=new Padding(10)};top.Controls.Add(new Label{Text="Native instrument bank",AutoSize=true});top.Controls.Add(bank);var match=Theme.Button("Auto match closest bank");top.Controls.Add(match);
            var grid=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Theme.Background,ForeColor=Color.Black,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false};
            grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Channel",ReadOnly=true,FillWeight=45});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="PC instrument",ReadOnly=true,FillWeight=130});grid.Columns.Add(new DataGridViewComboBoxColumn{Name="SNES sample / patch",FillWeight=180});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Transpose",FillWeight=55});grid.Columns.Add(new DataGridViewCheckBoxColumn{Name="Mute",FillWeight=40});
            grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Priority",ReadOnly=true,FillWeight=65});grid.CurrentCellDirtyStateChanged+=delegate{if(grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};
            var groups=source.Notes.GroupBy(n=>new{n.Channel,n.Program,Key=n.Channel==9?n.Key:-1}).OrderBy(g=>g.Key.Channel).ThenBy(g=>g.Key.Program).ToArray();
            Action refresh=delegate{var chosen=(NativeMusicBank)bank.SelectedItem;if(chosen==null)return;grid.Rows.Clear();var column=(DataGridViewComboBoxColumn)grid.Columns[2];column.DataSource=null;column.DisplayMember="Name";column.ValueMember="Id";column.DataSource=library.Select(i=>new NativeInstrument{Id=i.Id,Name=i.ToString(),Wave=i.Wave}).ToList();foreach(var group in groups){var assigned=settings.Assignments.FirstOrDefault(a=>a.Channel==group.Key.Channel&&a.Program==group.Key.Program&&(a.Key<0||a.Key==group.Key.Key));int patch=assigned!=null&&library.Any(i=>i.Id==assigned.Patch)?assigned.Patch:MusicBank.Closest(chosen,group.First());int row=grid.Rows.Add((group.Key.Channel+1).ToString(),group.Key.Channel==9?NativeVoicing.DrumName(group.Key.Key):MusicBank.ProgramName(group.Key.Program),patch,assigned==null?0:assigned.Transpose,assigned!=null&&assigned.Mute,PriorityName(assigned==null?0:assigned.Priority));grid.Rows[row].Cells[5].Tag=assigned==null?0:assigned.Priority;grid.Rows[row].Tag=group.First();}};
            Func<MusicSettings> collect=delegate{grid.EndEdit();var chosen=(NativeMusicBank)bank.SelectedItem;var result=new MusicSettings{Bank=chosen.Module,Origin=chosen.Origin,Song=chosen.Song,Grid=settings.Grid,VelocitySteps=settings.VelocitySteps};foreach(DataGridViewRow row in grid.Rows){var note=(MusicNote)row.Tag;int shift;Bin.Require(int.TryParse(Convert.ToString(row.Cells[3].Value),out shift)&&shift>=-48&&shift<=48,"Transpose must be -48..48 semitones.");int priority=Convert.ToInt32(row.Cells[5].Tag??0);result.Assignments.Add(new MusicAssignment{Channel=note.Channel,Program=note.Program,Key=note.Channel==9?note.Key:-1,Patch=Convert.ToInt32(row.Cells[2].Value),Priority=priority,Transpose=shift,Mute=Convert.ToBoolean(row.Cells[4].Value)});}MusicLibrary.Prepare(rom,result);return result;};
            bank.SelectedIndexChanged+=delegate{if(grid.Rows.Count>0)settings=collect();refresh();};bank.SelectedItem=banks.FirstOrDefault(b=>b.Module==settings.Bank)??banks[0];
            match.Click+=delegate{var previous=collect();var automatic=MusicBank.Automatic(rom,source);foreach(var assignment in automatic.Assignments){var old=previous.Assignments.FirstOrDefault(a=>a.Channel==assignment.Channel&&a.Program==assignment.Program&&a.Key==assignment.Key);if(old!=null){assignment.Mute=old.Mute;assignment.Transpose=old.Transpose;assignment.Priority=old.Priority;}}grid.Rows.Clear();settings=automatic;bank.SelectedItem=banks.First(b=>b.Module==settings.Bank);refresh();};
            foreach(bool mute in new[]{true,false}){bool value=mute;var bulk=Theme.Button(value?"Mute all":"Unmute all");bulk.Click+=delegate{grid.EndEdit();foreach(DataGridViewRow row in grid.Rows)row.Cells[4].Value=value;};top.Controls.Add(bulk);}
            foreach(bool mute in new[]{true,false}){bool value=mute;var channelButton=Theme.Button(value?"Mute channel":"Unmute channel");channelButton.Click+=delegate{if(grid.CurrentRow==null)return;grid.EndEdit();int channel=((MusicNote)grid.CurrentRow.Tag).Channel;foreach(DataGridViewRow row in grid.Rows)if(((MusicNote)row.Tag).Channel==channel)row.Cells[4].Value=value;};top.Controls.Add(channelButton);}
            var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=120,Padding=new Padding(10)};var preview=Theme.Button("Audition selected sample");var stop=Theme.Button("Stop");var ok=Theme.Button("Use assignments");var cancel=Theme.Button("Cancel");bottom.Controls.Add(preview);bottom.Controls.Add(stop);bottom.Controls.Add(ok);bottom.Controls.Add(cancel);bottom.Controls.Add(new Label{AutoSize=true,MaximumSize=new Size(850,0),Text="All native music patches are selectable. Mixed banks pack only the selected samples into SPC RAM. Auto matching separates melodic instruments from drums. Higher Priority preserves that part when voices are full. Native percussion pitches follow the retail kit; Transpose adjusts them. Mute channel includes all drum rows on channel 10. Accepting assignments rebuilds the SPC score. Priority decides which notes survive when the voice budget is full; it does not change the original MID/MUS file.",ForeColor=Theme.Muted});
            var automaticPreview=new CheckBox{Text="Audition selection (1 second)",Checked=true,AutoSize=true};bottom.Controls.Add(automaticPreview);
            int auditionGeneration=0;var debounce=new Timer{Interval=180};bool rendering=false;int pending=-1;
            Func<Task> audition=async delegate{if(rendering){pending=auditionGeneration;return;}int generation=++auditionGeneration;rendering=true;try{if(grid.CurrentRow==null)return;var row=grid.CurrentRow;var note=(MusicNote)row.Tag;int shift;int.TryParse(Convert.ToString(row.Cells[3].Value),out shift);int patch=Convert.ToInt32(row.Cells[2].Value);var current=new MusicSettings();current.Assignments.Add(new MusicAssignment{Channel=note.Channel,Program=note.Program,Key=note.Channel==9?note.Key:-1,Patch=patch,Transpose=shift});var input=new ImportedMusic{Name="Instrument audition",Seconds=1,Report=""};input.Notes.Add(new MusicNote{Start=0,End=.8,Channel=note.Channel,Program=note.Program,Key=note.Channel==9?note.Key:60,Velocity=100});byte[] wave=await Task.Run(delegate{MusicLibrary.Prepare(rom,current);var music=MusicImport.Convert(input,"E1M1",1,0,false,current);int rate;return NativeAudio.Wave(NativeAudio.Render(rom,MusicBank.PreviewRam(rom,music),0,current.Song,1,out rate));});if(IsDisposed||generation!=auditionGeneration)return;if(player!=null){player.Stop();player.Dispose();}if(stream!=null)stream.Dispose();stream=new System.IO.MemoryStream(wave);player=new System.Media.SoundPlayer(stream);player.Play();}catch(Exception ex){if(!IsDisposed&&generation==auditionGeneration)MessageBox.Show(this,ex.Message,"Audition");}finally{rendering=false;if(pending>=0&&!IsDisposed){pending=-1;debounce.Start();}}};
            Action schedule=delegate{if(!automaticPreview.Checked)return;auditionGeneration++;if(player!=null)player.Stop();debounce.Stop();debounce.Start();};
            debounce.Tick+=async delegate{debounce.Stop();await audition();};preview.Click+=async delegate{debounce.Stop();await audition();};
            grid.CellClick+=delegate(object sender,DataGridViewCellEventArgs e){if(e.RowIndex>=0&&e.ColumnIndex==2)schedule();};
            grid.EditingControlShowing+=delegate(object sender,DataGridViewEditingControlShowingEventArgs e){var combo=e.Control as ComboBox;if(combo==null)return;combo.SelectedIndexChanged-=SampleSelectionChanged;combo.SelectedIndexChanged+=SampleSelectionChanged;combo.SelectionChangeCommitted-=SampleSelectionChanged;combo.SelectionChangeCommitted+=SampleSelectionChanged;};
            sampleSelectionChanged=delegate(object sender,EventArgs e){var combo=sender as ComboBox;if(combo!=null&&combo.Focused&&combo.SelectedValue is int&&grid.CurrentRow!=null){grid.CurrentRow.Cells[2].Value=(int)combo.SelectedValue;schedule();}};
            foreach(var preset in new[]{new{Text="Background",Value=-4},new{Text="Normal",Value=0},new{Text="Important",Value=4},new{Text="Keep",Value=8}}){var choice=preset;var button=Theme.Button(choice.Text);button.Click+=delegate{if(grid.CurrentRow==null)return;grid.EndEdit();int channel=((MusicNote)grid.CurrentRow.Tag).Channel;foreach(DataGridViewRow row in grid.Rows)if(((MusicNote)row.Tag).Channel==channel){row.Cells[5].Tag=choice.Value;row.Cells[5].Value=PriorityName(choice.Value);}};top.Controls.Add(button);}top.Height=205;bottom.Height=150;var prioritySlider=new TrackBar{Minimum=0,Maximum=100,Value=50,TickFrequency=25,Width=280,Height=40};var priorityLabel=new Label{Text="Selected channel priority: Normal",AutoSize=true,Margin=new Padding(8,12,8,0)};top.SetFlowBreak(top.Controls[top.Controls.Count-1],true);top.Controls.Add(priorityLabel);top.Controls.Add(prioritySlider);top.Controls.Add(new Label{Text="Background  ->  Normal  ->  Keep",AutoSize=true,Margin=new Padding(8,12,8,0)});bool syncingPriority=false;Action syncPriority=delegate{if(grid.CurrentRow==null)return;syncingPriority=true;int value=Convert.ToInt32(grid.CurrentRow.Cells[5].Tag??0);prioritySlider.Value=Math.Max(0,Math.Min(100,(value+10)*5));priorityLabel.Text="Channel "+grid.CurrentRow.Cells[0].Value+" priority: "+PriorityName(value);syncingPriority=false;};grid.SelectionChanged+=delegate{syncPriority();};grid.CellValueChanged+=delegate(object sender,DataGridViewCellEventArgs e){if(e.ColumnIndex==5)syncPriority();};prioritySlider.ValueChanged+=delegate{if(syncingPriority||grid.CurrentRow==null)return;int channel=((MusicNote)grid.CurrentRow.Tag).Channel,value=prioritySlider.Value/5-10;foreach(DataGridViewRow row in grid.Rows)if(((MusicNote)row.Tag).Channel==channel){row.Cells[5].Tag=value;row.Cells[5].Value=PriorityName(value);}priorityLabel.Text="Channel "+(channel+1)+" priority: "+PriorityName(value);};syncPriority();
            FormClosed+=delegate{auditionGeneration++;debounce.Stop();debounce.Dispose();};
            stop.Click+=delegate{auditionGeneration++;pending=-1;debounce.Stop();if(player!=null)player.Stop();};ok.Click+=delegate{try{Settings=collect();DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Assignments");}};cancel.Click+=delegate{DialogResult=DialogResult.Cancel;Close();};FormClosed+=delegate{if(player!=null){player.Stop();player.Dispose();}if(stream!=null)stream.Dispose();};
            Controls.Add(grid);Controls.Add(bottom);Controls.Add(top);AcceptButton=ok;CancelButton=cancel;
        }
    }
}

